package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;import android.view.View;
final class WeatherMotion extends View {
 final int code;final boolean day,motion;final Paint pen=new Paint(3);boolean active=true;
 WeatherMotion(Context context,int weatherCode,boolean daylight,boolean animate){super(context);code=weatherCode;day=daylight;motion=animate;setContentDescription("Weather condition symbol");setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
 final Runnable tick=new Runnable(){public void run(){if(active&&motion&&isShown()&&getWindowVisibility()==VISIBLE){invalidate();postDelayed(this,80);}}};
 void running(boolean value){active=value;removeCallbacks(tick);if(value&&motion&&getVisibility()==VISIBLE)post(tick);}
 protected void onAttachedToWindow(){super.onAttachedToWindow();running(true);}protected void onDetachedFromWindow(){removeCallbacks(tick);super.onDetachedFromWindow();}protected void onWindowVisibilityChanged(int visibility){super.onWindowVisibilityChanged(visibility);if(tick!=null)running(active);}
 protected void onDraw(Canvas canvas){float time=motion?SystemClock.elapsedRealtime()/1000f:0;canvas.save();canvas.scale(getWidth()/100f,getHeight()/100f);pen.setColor(0xff353a3b);pen.setStrokeWidth(3);pen.setStrokeCap(Paint.Cap.ROUND);pen.setStrokeJoin(Paint.Join.ROUND);pen.setStyle(Paint.Style.STROKE);if(code<0){pen.setTextSize(48);pen.setStyle(Paint.Style.FILL);canvas.drawText("?",35,68,pen);canvas.restore();return;}if(code<=2){if(day){canvas.drawCircle(39,35,16,pen);canvas.save();canvas.rotate(time*12,39,35);for(int i=0;i<8;i++){canvas.save();canvas.rotate(i*45,39,35);canvas.drawLine(39,7,39,13,pen);canvas.restore();}canvas.restore();}else{Path moon=new Path();moon.moveTo(48,12);moon.cubicTo(15,10,14,59,50,57);moon.cubicTo(30,45,29,26,48,12);canvas.drawPath(moon,pen);}}if(code>=2){float drift=(float)Math.sin(time*.8f)*2;canvas.save();canvas.translate(drift,0);canvas.drawRoundRect(new RectF(18,40,84,65),12,12,pen);canvas.drawArc(new RectF(34,23,66,55),180,180,false,pen);canvas.restore();}boolean rain=code>=51&&code<=67||code>=80&&code<=82;boolean snow=code>=71&&code<=77||code==85||code==86;if(rain||snow)for(int i=0;i<3;i++){float x=30+i*20,y=72+(time*(rain?16:8)+i*5)%19;if(snow){canvas.drawLine(x-3,y,x+3,y,pen);canvas.drawLine(x,y-3,x,y+3,pen);}else canvas.drawLine(x,y,x-3,y+7,pen);}if(code==45||code==48){canvas.drawLine(20,76,80,76,pen);canvas.drawLine(29,86,88,86,pen);}if(code>=95){pen.setAlpha((int)(155+100*(.5+.5*Math.sin(time*3))));Path bolt=new Path();bolt.moveTo(53,67);bolt.lineTo(43,81);bolt.lineTo(56,81);bolt.lineTo(48,94);canvas.drawPath(bolt,pen);pen.setAlpha(255);}canvas.restore();}
}
